 if(argc!=4)throw std::invalid_argument("compute|rocket additions seed");const bool compute=std::string(argv[1])=="compute";if(!compute&&std::string(argv[1])!="rocket")throw std::invalid_argument("Unknown profile");const auto p=compute?Profile::Compute128:Profile::Rocket256;const unsigned h=compute?0:2,rounds=std::stoul(argv[2]);if(!rounds||rounds>100000)throw std::invalid_argument("Bounded addition count required");
 LiveBridgeCapability capability{IRIS_FIXTURE_INSTRUCTION_SHA,{}};for(auto raw:iris_fixture_instructions)capability.instructions.push_back({~0u,raw});SaturnLiveBridge bridge(p,h,std::stoul(argv[3]),capability);
 const auto fields=SaturnTimingCut::input_fields(p);std::map<std::string,unsigned>in,out;DefinedReferenceInputs inputs;inputs.values.words.resize(fields.size());for(unsigned n=0;n<fields.size();++n){in.emplace(std::string(fields[n].name),n);inputs.known_bits.push_back(fields[n].word_width==64?~0ULL:(1ULL<<fields[n].word_width)-1);}for(unsigned n=0;n<SaturnTimingCut::output_fields(p).size();++n)out.emplace(std::string(SaturnTimingCut::output_fields(p)[n].name),n);
