 set(compute?"io_status_prv":"io_core_status_prv",3);set(compute?"io_resp_ready":"io_core_resp_ready",1);const std::string config=compute?"io_ex_vconfig_":"io_core_ex_vconfig_";set(config+"vl",1);set(config+"vtype_vma",1);set(config+"vtype_vta",1);
